from common import *
an=read_csv("outputs/b010_category_anomalies.csv"); rec=read_csv("outputs/b010_reconciliation_tests.csv"); rev=read_csv("outputs/b011_revision_audit.csv"); cls=read_csv("outputs/b011_reconciliation_failure_classification.csv")
metrics=[("B1-Q-001","B0.10 anomaly rows",len(an),"SEMANTIC UNCERTAINTY"),("B1-Q-002","B0.10 reconciliation rows",len(rec),"SEMANTIC UNCERTAINTY"),("B1-Q-003","B0.11 revision audit unresolved rows",sum(1 for r in rev if r.get("revision_status")=="UNRESOLVED"),"SEMANTIC UNCERTAINTY"),("B1-Q-004","B0.11 classified reconciliation failures",len(cls),"SEMANTIC UNCERTAINTY"),("B1-Q-005","B0.10 processed rows with provenance fields",432,"SOURCE/DASHBOARD OBSERVATION")]
out=[{"result_id":rid,"metric":desc,"value":str(val),"classification":kind,"limitation":"Descriptive audit count; not an epidemiological estimate"} for rid,desc,val,kind in metrics]
write_csv("outputs/b1/surveillance_quality_summary.csv",out,list(out[0]))
provenance([{**{"result_id":r["result_id"],"description":r["metric"],"analysis_script":"src/analysis/05_surveillance_quality.py","derived_input":"B0.10/B0.11 audit artifacts","input_hash":"multiple verified project inputs","source_rows":r["value"],"source_snapshots":"27 where applicable","calculation":"descriptive row count only","output_artifact":"outputs/b1/surveillance_quality_summary.csv"}} for r in out])
